export default function VendorStatCard({label,value,detail}:{label:string;value:string|number;detail?:string}){return <article className="rounded-xl border bg-white p-5"><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-3xl font-bold">{value}</p>{detail&&<p className="mt-1 text-xs text-slate-500">{detail}</p>}</article>}
